args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:To_Sir,_with_Love dbr:Pesadilla_para_un_rico }
  ?film dbo:director ?director .
  ?director dbo:deathDate ?deathDate .
}
ORDER BY DESC(?deathDate)
LIMIT 1

